// ============ 设置系统 ============

/**
 * 获取所有设置
 */
export function getSettings() {
  try {
    const stored = localStorage.getItem(SETTINGS_KEY);
    if (!stored) return { ...DEFAULT_SETTINGS };
    return { ...DEFAULT_SETTINGS, ...JSON.parse(stored) };
  } catch {
    return { ...DEFAULT_SETTINGS };
  }
}

/**
 * 保存设置
 */
export function saveSettings(updates) {
  const current = getSettings();
  const merged = { ...current, ...updates };
  
  try {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(merged));
    return merged;
  } catch {
    return current;
  }
}

/**
 * 重置设置
 */
export function resetSettings() {
  localStorage.removeItem(SETTINGS_KEY);
  return { ...DEFAULT_SETTINGS };
}

/**
 * 更新嵌套设置
 */
export function updateSetting(path, value) {
  const settings = getSettings();
  
  // 支持 dot.path 格式
  const keys = path.split('.');
  let current = settings;
  
  for (let i = 0; i < keys.length - 1; i++) {
    if (typeof current[keys[i]] !== 'object') {
      current[keys[i]] = {};
    }
    current = current[keys[i]];
  }
  
  current[keys[keys.length - 1]] = value;
  saveSettings(settings);
  
  return settings;
}

// ============ 主题系统 ============

/**
 * 获取当前主题
 */
export function getCurrentTheme() {
  try {
    const stored = localStorage.getItem(THEME_KEY);
    if (!stored) return { ...DEFAULT_THEME };
    
    const themeId = JSON.parse(stored);
    const preset = PRESET_THEMES.find(t => t.id === themeId);
    return preset ? { ...preset } : { ...DEFAULT_THEME };
  } catch {
    return { ...DEFAULT_THEME };
  }
}

/**
 * 设置主题
 */
export function setTheme(themeId) {
  const preset = PRESET_THEMES.find(t => t.id === themeId);
  if (!preset) return false;
  
  localStorage.setItem(THEME_KEY, JSON.stringify(themeId));
  applyTheme(preset);
  
  return true;
}

/**
 * 应用主题到页面
 */
export function applyTheme(theme) {
  const root = document.documentElement;
  
  const colors = theme.colors;
  root.style.setProperty('--color-primary', colors.primary);
  root.style.setProperty('--color-secondary', colors.secondary);
  root.style.setProperty('--color-accent', colors.accent);
  root.style.setProperty('--color-background', colors.background);
  root.style.setProperty('--color-surface', colors.surface);
  root.style.setProperty('--color-surface-alt', colors.surfaceAlt);
  root.style.setProperty('--color-text', colors.text);
  root.style.setProperty('--color-text-secondary', colors.textSecondary);
  root.style.setProperty('--color-border', colors.border);
  root.style.setProperty('--color-success', colors.success);
  root.style.setProperty('--color-warning', colors.warning);
  root.style.setProperty('--color-error', colors.error);
  
  // 应用背景色
  document.body.style.backgroundColor = colors.background;
  document.body.style.color = colors.text;
  
  // 更新meta theme-color
  let metaTheme = document.querySelector('meta[name="theme-color"]');
  if (!metaTheme) {
    metaTheme = document.createElement('meta');
    metaTheme.name = 'theme-color';
    document.head.appendChild(metaTheme);
  }
  metaTheme.content = colors.background;
}

/**
 * 初始化主题
 */
export function initTheme() {
  const theme = getCurrentTheme();
  applyTheme(theme);
}

// ============ 快捷键系统 ============

/**
 * 获取所有快捷键
 */
export function getShortcuts() {
  try {
    const stored = localStorage.getItem(SHORTCUTS_KEY);
    if (!stored) return { ...DEFAULT_SHORTCUTS };
    return { ...DEFAULT_SHORTCUTS, ...JSON.parse(stored) };
  } catch {
    return { ...DEFAULT_SHORTCUTS };
  }
}

/**
 * 保存快捷键
 */
export function saveShortcuts(shortcuts) {
  try {
    localStorage.setItem(SHORTCUTS_KEY, JSON.stringify(shortcuts));
    return shortcuts;
  } catch {
    return getShortcuts();
  }
}

/**
 * 重置快捷键
 */
export function resetShortcuts() {
  localStorage.removeItem(SHORTCUTS_KEY);
  return { ...DEFAULT_SHORTCUTS };
}

/**
 * 更新单个快捷键
 */
export function updateShortcut(action, keyConfig) {
  const shortcuts = getShortcuts();
  shortcuts[action] = keyConfig;
  saveShortcuts(shortcuts);
  
  // 重新注册快捷键
  registerShortcuts();
  
  return shortcuts;
}

/**
 * 检查快捷键匹配
 */
export function matchShortcut(event, config) {
  if (!config) return false;
  
  const ctrlMatch = !!config.ctrl === (event.ctrlKey || event.metaKey);
  const shiftMatch = !!config.shift === event.shiftKey;
  const altMatch = !!config.alt === event.altKey;
  const keyMatch = config.key.toLowerCase() === event.key.toLowerCase();
  
  return ctrlMatch && shiftMatch && altMatch && keyMatch;
}

/**
 * 格式化快捷键显示
 */
export function formatShortcut(config) {
  if (!config) return '';
  
  const parts = [];
  if (config.ctrl) parts.push('Ctrl');
  if (config.shift) parts.push('Shift');
  if (config.alt) parts.push('Alt');
  parts.push(config.key);
  
  return parts.join(' + ');
}

/**
 * 注册全局快捷键
 */
const registeredHandlers = new Map();

export function registerShortcuts() {
  // 清除旧注册
  document.removeEventListener('keydown', handleKeyDown);
  
  const shortcuts = getShortcuts();
  
  // 注册每个快捷键
  for (const [action, config] of Object.entries(shortcuts)) {
    if (config && config.key) {
      registeredHandlers.set(action, config);
    }
  }
  
  // 添加全局监听
  document.addEventListener('keydown', handleKeyDown);
}

function handleKeyDown(event) {
  for (const [action, config] of registeredHandlers.entries()) {
    if (matchShortcut(event, config)) {
      event.preventDefault();
      handleShortcutAction(action);
      return;
    }
  }
}

// 快捷键动作处理
const shortcutHandlers = {};

export function registerShortcutHandler(action, handler) {
  shortcutHandlers[action] = handler;
}

function handleShortcutAction(action) {
  const handler = shortcutHandlers[action];
  if (handler) {
    handler();
  }
}

// ============ 导出/导入 ============

/**
 * 导出所有设置
 */
export function exportSettings() {
  return JSON.stringify({
    settings: getSettings(),
    theme: localStorage.getItem(THEME_KEY),
    shortcuts: getShortcuts()
  }, null, 2);
}

/**
 * 导入设置
 */
export function importSettings(jsonStr) {
  try {
    const data = JSON.parse(jsonStr);
    
    if (data.settings) {
      saveSettings(data.settings);
    }
    
    if (data.theme) {
      localStorage.setItem(THEME_KEY, data.theme);
      const themeId = JSON.parse(data.theme);
      const preset = PRESET_THEMES.find(t => t.id === themeId);
      if (preset) applyTheme(preset);
    }
    
    if (data.shortcuts) {
      saveShortcuts(data.shortcuts);
      registerShortcuts();
    }
    
    return true;
  } catch {
    return false;
  }
}

